START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory_Notifications" WHERE "MigrationId" = '20261111132501_AddNotificationTemplate') THEN
    CREATE TABLE notification_template (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TemplateKey" character varying(128) NOT NULL,
        "Language" character varying(16) NOT NULL,
        "Version" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        "Subject" text NOT NULL,
        "Text" text,
        "Html" text,
        "CreatedAt" timestamp with time zone NOT NULL,
        "CreatedBy" character varying(256),
        CONSTRAINT "PK_notification_template" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory_Notifications" WHERE "MigrationId" = '20261111132501_AddNotificationTemplate') THEN
    CREATE UNIQUE INDEX "UX_notification_template_active" ON notification_template ("TemplateKey", "Language") WHERE "IsActive" = TRUE;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory_Notifications" WHERE "MigrationId" = '20261111132501_AddNotificationTemplate') THEN
    CREATE UNIQUE INDEX "UX_notification_template_Key_Language_Version" ON notification_template ("TemplateKey", "Language", "Version");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory_Notifications" WHERE "MigrationId" = '20261111132501_AddNotificationTemplate') THEN
    INSERT INTO "__EFMigrationsHistory_Notifications" ("MigrationId", "ProductVersion")
    VALUES ('20261111132501_AddNotificationTemplate', '10.0.13');
    END IF;
END $EF$;
COMMIT;

